import urllib.request as u, urllib.error as ue, json, time, datetime as dt
B="http://localhost:8080"; tok=[None]; log=[]
def get(path):
    for _ in range(200):
        try:
            if tok[0] is None:
                tok[0]=json.load(u.urlopen(u.Request(B+"/token",method="POST",data=b"")))["token"]
            r=u.Request(B+path,headers={"Authorization":"Bearer "+tok[0]})
            return json.load(u.urlopen(r))
        except ue.HTTPError as e:
            body=e.read()[:200]; log.append((path,e.code,body))
            if e.code==404: return None
            if e.code==401: tok[0]=None; continue
            ra=e.headers.get("Retry-After")
            try: w=float(ra)
            except: 
                try: w=float(json.loads(body).get("retry_after",1))
                except: w=1
            time.sleep(w)
        except Exception as e:
            log.append((path,repr(e))); time.sleep(1)
    raise SystemExit("fail "+path)
seen={};dups=0;p=1
while True:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: print("DIFF",o,seen[o["id"]])
        else: seen[o["id"]]=o
    if not d["next"]: break
    p+=1
print("pages",p,"orders",len(seen),"dups",dups)
lo=dt.datetime(2025,3,1,tzinfo=dt.timezone.utc);hi=dt.datetime(2025,6,1,tzinfo=dt.timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in seen.values():
    if o["status"]!="shipped": continue
    t=dt.datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not lo<=t<hi: continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get("/customers/"+c)
    if cust[c] is None: print("missing cust",o); continue
    v=(o["amount_cents"]*(100-cust[c]["discount_pct"])+50)//100
    reg[cust[c]["region"]]+=v;n+=1
tot=sum(reg.values())
json.dump({"total_cents":tot,"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(tot,n,dups,reg,set((l[1]) for l in log))
